import{d as g,C as t,o as d,c as p,E as i,a3 as a}from"./chunks/framework.D4-ViStF.js";const c=JSON.parse('{"title":"艮为山","description":"艮为山，艮上艮下","frontmatter":{"title":"艮为山","description":"艮为山，艮上艮下","category":"hexagram","aliases":["艮","艮为山"],"source":["《周易》"]},"headers":[],"relativePath":"yijing/hexagrams/hexagram-52.md","filePath":"yijing/hexagrams/hexagram-52.md","lastUpdated":1787730063000}'),h={name:"yijing/hexagrams/hexagram-52.md"},x=g({...h,setup(m){const o=[{id:"gen",term:"艮",pinyin:"gèn",meaning:"止、静止；也是山。艮卦六爻每爻都以「艮其X」起头——在某处止住。",context:"卦德为「止」。"},{id:"genqizhi",term:"艮其趾",pinyin:"gèn qí zhǐ",meaning:"止于脚趾。脚趾是行动最先启动之处，止于趾，就是在最小的动处收住。"},{id:"yongzhen",term:"永贞",pinyin:"yǒng zhēn",meaning:"永远守正。「利永贞」：利于长久守住正道。"},{id:"genqifei",term:"艮其腓",pinyin:"gèn qí féi",meaning:"止于小腿肚。腓随脚而动，自己作不了主。"},{id:"buzhengqisui",term:"不拯其随",pinyin:"bù zhěng qí suí",meaning:"不能挽救所跟随的。六二被九三带着走，止不住，也救不了。"},{id:"genqixian",term:"艮其限",pinyin:"gèn qí xiàn",meaning:"止于腰胯。限是上下半身的交界处。"},{id:"lieqiyin",term:"列其夤",pinyin:"liè qí yín",meaning:"夹脊的肌肉像撕裂一样。列通裂，夤为夹脊肉。"},{id:"xunxin",term:"薰心",pinyin:"xūn xīn",meaning:"忧危之气像火一样熏灼内心。「厉薰心」：危险得心被熏灼。"},{id:"genqishen",term:"艮其身",pinyin:"gèn qí shēn",meaning:"止于整个身体。止从局部（趾、腓）走到整体。"},{id:"genqifu",term:"艮其辅",pinyin:"gèn qí fǔ",meaning:"止于面颊。辅为面颊、口之所在，止于辅即管住嘴。"},{id:"yanyouxu",term:"言有序",pinyin:"yán yǒu xù",meaning:"说话有次序、有分寸。心里有数，嘴上才有序。"},{id:"dungen",term:"敦艮",pinyin:"dūn gèn",meaning:"厚重笃实的止。不再止于某一部位，而是整个人都在止。"}],e=[{position:"初六",type:"yin",text:"艮其趾，无咎，利永贞。",xiang:"艮其趾，未失正也。",textModern:"止于脚趾，没有灾祸，利于永远守正。",xiangModern:"止于脚趾，是因为没有失掉正——在最小的动处先立住根本。"},{position:"六二",type:"yin",text:"艮其腓，不拯其随，其心不快。",xiang:"不拯其随，未退听也。",textModern:"止于小腿，却挽救不了所跟随的，心里不痛快。",xiangModern:"救不了所跟随的，是因为还没有退下来、听从自己的内心。"},{position:"九三",type:"yang",text:"艮其限，列其夤，厉薰心。",xiang:"艮其限，危薰心也。",textModern:"止于腰胯，夹脊的肌肉像撕裂一样，危险得心被熏灼。",xiangModern:"在腰胯处硬止、强行分离上下，所以危险熏灼内心。"},{position:"六四",type:"yin",text:"艮其身，无咎。",xiang:"艮其身，止诸躬也。",textModern:"止于整个身体，没有灾祸。",xiangModern:"止于身体，是把止落在自己这个人身上。"},{position:"六五",type:"yin",text:"艮其辅，言有序，悔亡。",xiang:"艮其辅，以中正也。",textModern:"止于面颊，说话有次序、有分寸，悔恨消失。",xiangModern:"止于面颊，是因为居中得正——心里有数，嘴上才有序。"},{position:"上九",type:"yang",text:"敦艮，吉。",xiang:"敦艮之吉，以厚终也。",textModern:"厚重笃实的止，吉祥。",xiangModern:"敦艮的吉祥，是因为以厚重收尾。"}];return(u,n)=>{const r=t("DaoHexagramViewer"),l=t("DaoHexagramYaoCards"),s=t("DaoKeywordCards");return d(),p("div",null,[i(r,{name:"艮为山",fullName:"艮为山",upper:"☶",lower:"☶",guaCi:"艮其背，不获其身。行其庭，不见其人。无咎。",pinyin:["gèn","wéi","shān"],element:"土",direction:"东北",virtue:"止",insight:"知止而后有定，定而后能静。",guaSlug:"52genweishan",lines:e}),n[0]||(n[0]=a('<h2 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to &quot;象传&quot;">​</a></h2><p>兼山，艮。君子以思不出其位。</p><p>两座山叠在一起，山外有山——每一座都稳稳立在自己的位置上，互不越界，这就是艮。君子由此悟到：<strong>思不出其位</strong>，思考不要越过自己的位置。</p><p>「思不出其位」不是不思考，是不越位思考。位，是身份、职责、当下的处境。在什么山头，想什么事；手伸不到的地方，念头先收回来。</p><p>分形结构：</p><ul><li>止于身（身体）→ 微观：管住言行，先收住自己</li><li>止于位（位置）→ 宏观：守住边界，不越本位</li></ul><p>身是小些的位，位是大些的身。先止得住身，才谈得上守得住位。</p><h2 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to &quot;彖传&quot;">​</a></h2><p>艮，止也。时止则止，时行则行，动静不失其时，其道光明。艮其止，止其所也。上下敌应，不相与也。是以不获其身，行其庭不见其人，无咎也。</p><p>逐句释义：</p><ul><li><strong>艮，止也</strong> —— 艮卦的核心就是一个「止」字。</li><li><strong>时止则止，时行则行，动静不失其时</strong> —— 该停就停，该走就走；动与静都不错过时机。止不是永远不动，是<strong>随时而止</strong>。</li><li><strong>其道光明</strong> —— 这样一路走下来，路越走越亮。</li><li><strong>艮其止，止其所也</strong> —— 止于该止之处。止要有对象、有位置，不是空止。</li><li><strong>上下敌应，不相与也</strong> —— 上下卦六爻全部敌应（初与四皆阴、二与五皆阴、三与上皆阳），没有一爻相应。全卦无应，正是一心独止的象。</li><li><strong>是以不获其身，行其庭不见其人，无咎也</strong> —— 所以忘掉自身，走过庭院也看不见别人，没有灾祸。</li></ul><blockquote><p><strong>止的哲学</strong>：止不是终止，是定。定住了，才能看见。山不是不动，是稳稳立住；立住了，才看得清脚下的路。</p></blockquote><h2 id="六爻" tabindex="-1">六爻 <a class="header-anchor" href="#六爻" aria-label="Permalink to &quot;六爻&quot;">​</a></h2>',13)),i(l,{element:"土",guaSlug:"52genweishan",glossary:o,items:e}),n[1]||(n[1]=a('<h2 id="六爻详解" tabindex="-1">六爻详解 <a class="header-anchor" href="#六爻详解" aria-label="Permalink to &quot;六爻详解&quot;">​</a></h2><h3 id="初六-·-艮其趾-无咎-利永贞" tabindex="-1">初六 · 艮其趾，无咎，利永贞 <a class="header-anchor" href="#初六-·-艮其趾-无咎-利永贞" aria-label="Permalink to &quot;初六 · 艮其趾，无咎，利永贞&quot;">​</a></h3><ul><li><strong>艮其趾</strong> → 止于脚趾，行动最早启动之处</li><li><strong>无咎</strong> → 没有灾祸</li><li><strong>利永贞</strong> → 利于永远守正</li></ul><p>初六在卦的最下端。人的行动从脚起，脚的行动从趾起。<strong>止于趾</strong>，是在动作还没发出之前就收住——用对最小的力，立住最根本的「正」。</p><p>象曰「未失正也」：没有失掉正。站桩脚趾抓地——根基用对力，力从脚底生，全身才有支点。</p><blockquote><p>核心洞见：初六的「无咎」是预示之吉——在最小处用对力，后面的每一步都省力。</p></blockquote><h3 id="六二-·-艮其腓-不拯其随-其心不快" tabindex="-1">六二 · 艮其腓，不拯其随，其心不快 <a class="header-anchor" href="#六二-·-艮其腓-不拯其随-其心不快" aria-label="Permalink to &quot;六二 · 艮其腓，不拯其随，其心不快&quot;">​</a></h3><ul><li><strong>艮其腓</strong> → 止于小腿肚</li><li><strong>不拯其随</strong> → 不能挽救所跟随的（九三）</li><li><strong>其心不快</strong> → 心里不痛快</li></ul><p>腓是小腿，随脚而动，自己作不了主。六二阴爻居柔位，被九三带着走——想停，停不下来；想救，救不了。于是「其心不快」。</p><p>象曰「未退听也」：还没有退下来、听从自己的内心。</p><p><strong>家庭聚会不演了</strong>：被裹在热闹里，明明不快，还要陪笑。六二教的是——承认不快，就是这一爻的止。不再硬撑、不再表演，承认「此刻我做不了主」。</p><blockquote><p>核心洞见：止的功课不是控制一切，而是承认「此刻我止不住」。承认，本身就是一种止。</p></blockquote><h3 id="九三-·-艮其限-列其夤-厉薰心" tabindex="-1">九三 · 艮其限，列其夤，厉薰心 <a class="header-anchor" href="#九三-·-艮其限-列其夤-厉薰心" aria-label="Permalink to &quot;九三 · 艮其限，列其夤，厉薰心&quot;">​</a></h3><ul><li><strong>艮其限</strong> → 止于腰胯，上下半身的交界</li><li><strong>列其夤</strong> → 夹脊的肌肉像撕裂一样</li><li><strong>厉薰心</strong> → 危险得心像被熏灼</li></ul><p>九三阳爻居阳位，刚强过甚，想硬生生把上下的动都「止」住，结果在腰上裂开了——上身下身强行分离，忧危之气直冲心口。</p><p><strong>母亲进ICU签字那一刻</strong>：身体被撕开，心被熏灼。但九三这一爻的「厉」不是结局——危险只是过关的通道。裂过，才懂得「限」不能硬止，只能由下而上地止。</p><blockquote><p>核心洞见：九三的「列」是必经之痛。腰裂过，但脚趾没松——危险不是结局，是渡。</p></blockquote><h3 id="六四-·-艮其身-无咎" tabindex="-1">六四 · 艮其身，无咎 <a class="header-anchor" href="#六四-·-艮其身-无咎" aria-label="Permalink to &quot;六四 · 艮其身，无咎&quot;">​</a></h3><ul><li><strong>艮其身</strong> → 止于整个身体</li><li><strong>无咎</strong> → 没有灾祸</li></ul><p>六四阴爻居柔位，得位。止从局部（趾、腓）走到了整体（身）——开始能稳住自己整个的人。</p><p><strong>艮其背是果，艮其身是因</strong>：卦辞的「艮其背」是忘掉自己，是果；六四的「艮其身」是先认清自己，是因。先止住自己，才谈得上忘掉自己。</p><blockquote><p>核心洞见：背不用力、看不见，是果；身要用力、看得见，是因。先认清自己，才能不获其身。</p></blockquote><h3 id="六五-·-艮其辅-言有序-悔亡" tabindex="-1">六五 · 艮其辅，言有序，悔亡 <a class="header-anchor" href="#六五-·-艮其辅-言有序-悔亡" aria-label="Permalink to &quot;六五 · 艮其辅，言有序，悔亡&quot;">​</a></h3><ul><li><strong>艮其辅</strong> → 止于面颊（口）</li><li><strong>言有序</strong> → 说话有次序、有分寸</li><li><strong>悔亡</strong> → 悔恨消失</li></ul><p>六五阴爻居君位，是「止」的枢纽之位。止的功课走到这一爻，落在最难管的器官上——嘴。止于言语：<strong>知道什么时候说、对谁说、说多少</strong>。</p><p>象曰「以中正也」：居中得正。言有序，是因为心里有数；心里有数，是因为止得住。</p><blockquote><p>核心洞见：说得少而准，比说得多而杂更有力。止于言语，是止里最贵的一课。</p></blockquote><h3 id="上九-·-敦艮-吉" tabindex="-1">上九 · 敦艮，吉 <a class="header-anchor" href="#上九-·-敦艮-吉" aria-label="Permalink to &quot;上九 · 敦艮，吉&quot;">​</a></h3><ul><li><strong>敦艮</strong> → 厚重笃实的止</li><li><strong>吉</strong> → 吉祥</li></ul><p>上九居卦之终，止到了最深处。前五爻都是「艮其X」——止在某一个部位；上九没有部位，它是整个人的止：<strong>身形神一致</strong>，厚重、笃实。</p><p>象曰「以厚终也」：以厚重收尾。</p><p><strong>初六之吉是预示，上九之吉是印证</strong>：初六在起点用对了力，所以吉；上九走到终点，吉是被兑现的确认。</p><blockquote><p>核心洞见：敦艮不是学会的，是长出来的——厚重到一定程度，止自然成。这叫「以厚终」。</p></blockquote><h2 id="【原典层】字词释义" tabindex="-1">【原典层】字词释义 <a class="header-anchor" href="#【原典层】字词释义" aria-label="Permalink to &quot;【原典层】字词释义&quot;">​</a></h2>',34)),i(s,{title:"字词释义",items:[{term:"艮",pinyin:["gèn"],meaning:"止、静止；也是山。兼山为艮，两山相叠，止而不动。卦德为「止」。"},{term:"艮其背",pinyin:["gèn","qí","bèi"],meaning:"止于背。背是人看不见、最不受念想干扰之处；卦辞从背说起，取内收静定之意。"},{term:"不获其身",pinyin:["bù","huò","qí","shēn"],meaning:"感觉不到自己的存在。忘了自身，才止得住。"},{term:"行其庭不见其人",pinyin:["xíng","qí","tíng","bù","jiàn","qí","rén"],meaning:"走过庭院也看不见别人。心不向外，则外物不入。"},{term:"兼山",pinyin:["jiān","shān"],meaning:"两座山重叠，山外有山，止中有止。"},{term:"思不出其位",pinyin:["sī","bù","chū","qí","wèi"],meaning:"思考不越过自己本分的位置。"},{term:"艮其趾",pinyin:["gèn","qí","zhǐ"],meaning:"止于脚趾，行动最早启动之处，最小的动。"},{term:"艮其腓",pinyin:["gèn","qí","féi"],meaning:"止于小腿肚。腓不能自主，随脚而动。"},{term:"不拯其随",pinyin:["bù","zhěng","qí","suí"],meaning:"不能挽救所跟随的人；止不住，也救不了。"},{term:"艮其限",pinyin:["gèn","qí","xiàn"],meaning:"止于腰胯，上下半身的交界处。"},{term:"列其夤",pinyin:["liè","qí","yín"],meaning:"夹脊肉撕裂。列通裂，夤为夹脊肉。"},{term:"薰心",pinyin:["xūn","xīn"],meaning:"熏灼内心。忧危之气上行入心。"},{term:"艮其辅",pinyin:["gèn","qí","fǔ"],meaning:"止于面颊、管住嘴。辅为口之所在。"},{term:"敦艮",pinyin:["dūn","gèn"],meaning:"厚重笃实的止，整个人都在止。"}]}),n[2]||(n[2]=a('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一卦在说什么" tabindex="-1">象：这一卦在说什么 <a class="header-anchor" href="#象-这一卦在说什么" aria-label="Permalink to &quot;象：这一卦在说什么&quot;">​</a></h3><p>艮是八卦里唯一以「止」为德的卦，两艮相叠成「兼山」，把「止」强调到极致。卦辞「艮其背，不获其身。行其庭，不见其人」——止于最不受干扰的背，忘掉自己的存在，走过庭院也看不见人。这是极致的<strong>内收与静定</strong>。</p><p>核心：艮的「止」不是终止，是定——定住了，才能看见。</p><h3 id="理-为什么这一卦重要" tabindex="-1">理：为什么这一卦重要 <a class="header-anchor" href="#理-为什么这一卦重要" aria-label="Permalink to &quot;理：为什么这一卦重要&quot;">​</a></h3><p>人一生的问题大多不是「动不够」，而是「止不住」——停不下来、收不回来、认不清自己。艮卦把「止」拆成一条从身体到心的路径：趾→腓→限→身→辅→敦，一爻一爻收回来。</p><p>止不是消极，是积极的静：定住自己，才看得见处境；定住自己，才看得见别人。</p><h3 id="用-今天如何应用" tabindex="-1">用：今天如何应用 <a class="header-anchor" href="#用-今天如何应用" aria-label="Permalink to &quot;用：今天如何应用&quot;">​</a></h3><ol><li>从小处止起：先止住最小的动（趾），再谈止住整个身</li><li>承认止不住的部分：不硬撑、不表演，承认不快</li><li>撕裂是过关：腰裂过，但脚趾没松</li><li>先认清自己，再忘掉自己：艮其身是因，艮其背是果</li><li>止于言语：知道什么时候说、对谁说、说多少</li><li>让止成为敦：不停留在某一爻，让它厚重成整个人的状态</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>艮卦的完整地图：</p><table tabindex="0"><thead><tr><th>爻位</th><th>爻辞要点</th><th>功课</th><th>关键词</th></tr></thead><tbody><tr><td>卦辞</td><td>艮其背，不获其身，行其庭不见其人</td><td>止于最不受干扰处，忘掉自己</td><td>静定</td></tr><tr><td>初六</td><td>艮其趾，无咎，利永贞</td><td>最小处用对力，站桩脚趾抓地</td><td>根基</td></tr><tr><td>六二</td><td>艮其腓，不拯其随，其心不快</td><td>承认被带着走，不演了</td><td>接受</td></tr><tr><td>九三</td><td>艮其限，列其夤，厉薰心</td><td>腰裂是必经，危险不是结局</td><td>撕裂</td></tr><tr><td>六四</td><td>艮其身，无咎</td><td>先认清自己</td><td>认清</td></tr><tr><td>六五</td><td>艮其辅，言有序，悔亡</td><td>止于言语，知道给谁说多少</td><td>言语</td></tr><tr><td>上九</td><td>敦艮，吉</td><td>厚重笃实，身形神一致</td><td>印证</td></tr></tbody></table><p>核心洞见：</p><ol><li><strong>止不是终止，是定</strong>——定住了才能看见</li><li><strong>止是时机的艺术</strong>——时止则止，时行则行，动静不失其时</li><li><strong>身体是止的路径</strong>——从脚趾到背，一爻一爻收回来</li><li><strong>承认不快也是止</strong>——不硬撑、不表演</li><li><strong>危险不是结局</strong>——腰裂过，但脚趾没松</li><li><strong>艮其背是果，艮其身是因</strong>——先认清自己，才能忘掉自己</li><li><strong>止于言语最贵</strong>——言有序，悔亡</li><li><strong>初六之吉是预示，上九之吉是印证</strong></li></ol><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><p>艮卦与Dao的对应，是一条从脚到心的修行线：</p><ul><li><strong>趾抓紧Dao</strong> → 脚跟落地，根基用对力</li><li><strong>腓随着Dao走</strong> → 承认被带着走，不再硬撑</li><li><strong>腰裂过但脚趾没松</strong> → 裂过的伤，是Dao留下的印</li><li><strong>身长出Dao</strong> → 止从局部长成整体</li><li><strong>辅传递Dao</strong> → 言有序，把Dao说出去</li><li><strong>敦艮，Dao遂成</strong> → 厚重到一定程度，止自然成</li></ul><p><strong>「艮卦不是学会的，是感受到的。」</strong> 止不是靠命令自己「不要动」，而是在某个时刻<strong>感受到</strong>「该止了」。感受到的止，才是敦艮；学来的止，只是「艮其限」——硬止，会裂。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>相关卦象：震（第五十一卦）——震起也，艮止也，动与止是同一件事的两面：知道何时动，才知道何时止；渐（第五十三卦）——渐讲渐进，艮讲知止，进中要知止，止后能再进</li><li>相关概念：止、定、静、知止而后有定</li><li>相关专题：<a href="/Dao/topics/yin-yang">阴阳</a>、<a href="/Dao/topics/xiang-shu-li">象数理</a>、<a href="/Dao/topics/wu-wei">无为</a></li></ul>',20))])}}});export{c as __pageData,x as default};
